import sys

def solve():
    input = sys.stdin.buffer.readline
    first = input().split()
    if not first:
        return
    n, m = map(int, first)
    adj = [[] for _ in range(n + 1)]

    for _ in range(m):
        x, y = map(int, input().split())
        adj[x].append(y)
        adj[y].append(x)

    visited = [False] * (n + 1)

    for start in range(1, n + 1):
        if visited[start]:
            continue

        comp = []
        visited[start] = True
        stack = [start]

        while stack:
            x = stack.pop()
            comp.append(x)
            for y in adj[x]:
                if not visited[y]:
                    visited[y] = True
                    stack.append(y)

        k = len(comp)
        if k <= 1:
            continue

        degsum = 0
        for v in comp:
            degsum += len(adj[v])

        if degsum // 2 == k * (k - 1) // 2:
            continue

        u = -1
        for v in comp:
            if len(adj[v]) < k - 1:
                u = v
                break

        neighbors = set(adj[u])
        for v in comp:
            if v != u and v not in neighbors:
                sys.stdout.write(f"{u} {v}\n")
                return

    sys.stdout.write("-1\n")

if __name__ == "__main__":
    solve()
